import {
  Group,
  BoxGeometry,
  MeshStandardNodeMaterial,
  Mesh,
  PointLight,
  Vector3
} from 'three/webgpu';
import { color, vec3 } from 'three/tsl';
import { gsap } from 'gsap';

export function createNode(config, ctx) {
  const { THREE } = ctx;
  const group = new Group();

  // Create local GSAP timeline references for cleanup
  const timelines = [];

  // Parse color tokens
  const palette = config.colors ?? {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10'
  };

  // 1. Stage / Card base: A machined-metal card base to frame the gear
  const cardWidth = 2.4;
  const cardHeight = 3.2;
  const cardDepth = 0.08;

  const baseGeo = new BoxGeometry(cardWidth, cardHeight, cardDepth);

  // High fidelity PBR material for machined-metal look
  const baseMat = new MeshStandardNodeMaterial({
    color: palette.surface,
    roughness: 0.52,
    metalness: 0.55,
    clearcoat: 0.25,
    clearcoatRoughness: 0.1
  });

  const cardBase = new Mesh(baseGeo, baseMat);
  cardBase.castShadow = true;
  cardBase.receiveShadow = true;
  group.add(cardBase);

  // Accent outline/rim highlighting (accent edge on focus / hover)
  const edgeGeo = new BoxGeometry(cardWidth + 0.04, cardHeight + 0.04, 0.02);
  const edgeMat = new MeshStandardNodeMaterial({
    color: palette.accent,
    emissive: palette.accent,
    emissiveIntensity: 0.2,
    roughness: 0.2,
    metalness: 0.8
  });
  const accentEdge = new Mesh(edgeGeo, edgeMat);
  accentEdge.position.z = -0.04;
  accentEdge.scale.set(0.98, 0.98, 1); // Hidden slightly behind initially
  group.add(accentEdge);

  // 2. Load and Position the 3D Gear Mesh
  let gearMesh = null;
  if (config.meshUrl) {
    ctx.glbLoader.loadGLB(config.meshUrl).then((gltf) => {
      gearMesh = gltf.scene;

      // Auto-scale and center the gear inside the frame
      const box = new THREE.Box3().setFromObject(gearMesh);
      const size = box.getSize(new Vector3());
      const maxDim = Math.max(size.x, size.y, size.z);
      const scaleFactor = 1.3 / maxDim;
      gearMesh.scale.setScalar(scaleFactor);

      // Center the mesh visually
      const center = box.getCenter(new Vector3());
      gearMesh.position.sub(center.multiplyScalar(scaleFactor));
      gearMesh.position.z += 0.15; // Push slightly forward from the base plate

      // Apply tailored PBR properties to the gear's child meshes
      gearMesh.traverse((child) => {
        if (child.isMesh) {
          child.castShadow = true;
          child.receiveShadow = true;
          if (child.material) {
            child.material.roughness = 0.4;
            child.material.metalness = 0.8;
          }
        }
      });

      group.add(gearMesh);

      // Start an elegant slow continuous rotation for the gear (Atelier concept)
      const idleTween = gsap.to(gearMesh.rotation, {
        y: Math.PI * 2,
        duration: 16,
        repeat: -1,
        ease: 'none'
      });
      timelines.push(idleTween);
    }).catch(err => {
      console.warn("Failed to load gear mesh", err);
    });
  }

  // 3. Local Lighting to emphasize product-shot fidelity & accent color
  const localKeyLight = new PointLight(palette.paper, 1.4, 6);
  localKeyLight.position.set(2, 2, 3);
  group.add(localKeyLight);

  const localRimLight = new PointLight(palette.accent, 1.2, 4);
  localRimLight.position.set(-2, -2, 1);
  group.add(localRimLight);

  // 4. Interactive State Handlers
  let isHovered = false;

  group.userData.handlers = {
    pointerover: () => {
      if (isHovered) return;
      isHovered = true;

      // Hover preset: rise-in (subtle lift + accent highlight reveal)
      const hoverTl = gsap.timeline();
      hoverTl.to(group.position, {
        y: -0.2 + 0.15, // Rise subtle 0.15 scene units
        z: 0.1,
        duration: 0.4,
        ease: 'power2.out'
      }, 0);

      hoverTl.to(accentEdge.scale, {
        x: 1.01,
        y: 1.01,
        duration: 0.3,
        ease: 'back.out(1.7)'
      }, 0);

      hoverTl.to(accentEdge.material, {
        emissiveIntensity: 1.2,
        duration: 0.3
      }, 0);

      if (gearMesh) {
        hoverTl.to(gearMesh.position, {
          z: 0.25,
          duration: 0.4,
          ease: 'power3.out'
        }, 0);
      }

      timelines.push(hoverTl);
    },

    pointerout: () => {
      isHovered = false;
      const leaveTl = gsap.timeline();
      leaveTl.to(group.position, {
        y: -0.2,
        z: 0,
        duration: 0.5,
        ease: 'power2.out'
      }, 0);

      leaveTl.to(accentEdge.scale, {
        x: 0.98,
        y: 0.98,
        duration: 0.4,
        ease: 'power2.out'
      }, 0);

      leaveTl.to(accentEdge.material, {
        emissiveIntensity: 0.2,
        duration: 0.4
      }, 0);

      if (gearMesh) {
        leaveTl.to(gearMesh.position, {
          z: 0.15,
          duration: 0.5,
          ease: 'power3.out'
        }, 0);
      }

      timelines.push(leaveTl);
    },

    click: () => {
      // Press-down interactive click motion
      const clickTl = gsap.timeline();
      clickTl.to(group.scale, {
        x: 0.96,
        y: 0.96,
        z: 0.96,
        duration: 0.1,
        ease: 'power2.out'
      });
      clickTl.to(group.scale, {
        x: 1,
        y: 1,
        z: 1,
        duration: 0.3,
        ease: 'back.out(2)'
      });

      timelines.push(clickTl);

      // Trigger navigation event
      ctx.emit('hub-home.select', { id: config.id ?? 'gear-a' });
    }
  };

  // 5. Cleanup Lifecycle Hook
  group.userData.cleanup = () => {
    timelines.forEach(tl => tl.kill());
    baseGeo.dispose();
    baseMat.dispose();
    edgeGeo.dispose();
    edgeMat.dispose();
  };

  return group;
}
